-- AquaCheck · DATOS DE PRUEBA FICTICIOS (solo para ensayar el panel del equipo)
-- Celulares 900 000 0NN (ficticios), consentimiento marcado 'datos-de-prueba'. Fechas relativas a hoy.
-- ANTES DEL PILOTO REAL hay que ejecutar seed/borrar_datos_de_prueba.sql (deja los 20 hogares sin registrar).
-- Importante: mientras estén cargados, los QR reales de AQ-001..AQ-017 abrirían un hogar "ya registrado". No repartir QR antes de borrar.
update hogares set registrado = true, fecha_instalacion = current_date - 200 where codigo = 'AQ-001';
update hogares set registrado = true, fecha_instalacion = current_date - 200 where codigo = 'AQ-002';
update hogares set registrado = true, fecha_instalacion = current_date - 150 where codigo = 'AQ-003';
update hogares set registrado = true, fecha_instalacion = current_date - 240 where codigo = 'AQ-004';
update hogares set registrado = true, fecha_instalacion = current_date - 240 where codigo = 'AQ-005';
update hogares set registrado = true, fecha_instalacion = current_date - 90 where codigo = 'AQ-006';
update hogares set registrado = true, fecha_instalacion = current_date - 60 where codigo = 'AQ-007';
update hogares set registrado = true, fecha_instalacion = current_date - 100 where codigo = 'AQ-008';
update hogares set registrado = true, fecha_instalacion = current_date - 30 where codigo = 'AQ-009';
update hogares set registrado = true, fecha_instalacion = current_date - 20 where codigo = 'AQ-010';
update hogares set registrado = true, fecha_instalacion = current_date - 180 where codigo = 'AQ-011';
update hogares set registrado = true, fecha_instalacion = current_date - 180 where codigo = 'AQ-012';
update hogares set registrado = true, fecha_instalacion = current_date - 75 where codigo = 'AQ-013';
update hogares set registrado = true, fecha_instalacion = current_date - 45 where codigo = 'AQ-014';
update hogares set registrado = true, fecha_instalacion = current_date - 120 where codigo = 'AQ-015';
